using System.Text.Json;using JobOrbit.Application.Auditing;using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Entities;using JobOrbit.Infrastructure.Persistence;
namespace JobOrbit.API.Services;public sealed class AuditService(JobOrbitDbContext db,IHttpContextAccessor accessor):IAuditService{public async Task WriteAsync(AuditEvent e,CancellationToken t=default){var h=accessor.HttpContext;db.AuditLogs.Add(new AuditLog{UserId=e.ActorUserId,Action=e.Action,EntityName=e.EntityType,EntityId=e.EntityId,EntityDisplayName=e.EntityDisplayName,Description=e.Description,Severity=e.Severity,IsSuccess=e.IsSuccess,OldValues=e.OldValues==null?null:JsonSerializer.Serialize(e.OldValues),NewValues=e.NewValues==null?null:JsonSerializer.Serialize(e.NewValues),Metadata=e.Metadata==null?null:JsonSerializer.Serialize(e.Metadata),IpAddress=h?.Connection.RemoteIpAddress?.ToString(),UserAgent=h?.Request.Headers.UserAgent.ToString(),CorrelationId=e.CorrelationId??h?.TraceIdentifier});await db.SaveChangesAsync(t);}}
